from __future__ import annotations

import subprocess
import sys
from pathlib import Path


def test_legacy_pytest_suite() -> None:
    local_test = Path(__file__).with_name("test_outputs.py")
    harness_test = Path("/tests/test_outputs.py")
    test_file = harness_test if harness_test.exists() else local_test

    result = subprocess.run(
        [sys.executable, "-m", "pytest", str(test_file), "-q"],
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        raise AssertionError((result.stdout or "") + "\n" + (result.stderr or ""))



# --- test_outputs.py ---
import json
from pathlib import Path
GROUND_TRUTH = Path('/tests/expected_output.json')
OUTPUT_FILE = Path('/root/answers.json')

def load_json(path):
    with open(path) as f:
        return json.load(f)

def json_close(actual, expected, tol=0.01):
    """Compare two JSON structures with numeric tolerance."""
    if isinstance(actual, dict) and isinstance(expected, dict):
        if set(actual.keys()) != set(expected.keys()):
            return False, f"Key mismatch: {set(actual.keys())} vs {set(expected.keys())}"
        for k in expected:
            ok, msg = json_close(actual[k], expected[k], tol)
            if not ok:
                return False, f"At key '{k}': {msg}"
        return True, ""
    elif isinstance(actual, list) and isinstance(expected, list):
        if len(actual) != len(expected):
            return False, f"Length mismatch: {len(actual)} vs {len(expected)}"
        for i in range(len(actual)):
            ok, msg = json_close(actual[i], expected[i], tol)
            if not ok:
                return False, f"At index {i}: {msg}"
        return True, ""
    elif isinstance(actual, (int, float)) and isinstance(expected, (int, float)):
        if abs(float(actual) - float(expected)) > tol:
            return False, f"Numeric mismatch: {actual} vs {expected} (tol={tol})"
        return True, ""
    elif isinstance(actual, str) and isinstance(expected, str):
        if actual.strip() != expected.strip():
            return False, f"String mismatch: '{actual}' vs '{expected}'"
        return True, ""
    else:
        if actual != expected:
            return False, f"Value mismatch: {actual} vs {expected}"
        return True, ""

def test_file_exists():
    assert OUTPUT_FILE.is_file()


def test_answers():
    actual = load_json(OUTPUT_FILE)
    expected = load_json(GROUND_TRUTH)
    ok, msg = json_close(actual, expected)
    assert ok, msg

tasks.description:
Create `/root/answers.json` from the filing data in `/root/2025-q3`.

Build a manager-versus-issuer grid for two manager queries and two issuer queries.

Return a JSON object with exactly this shape:

```json
{
  "manager_issuer_grid": [
    {
      "fund_query": "bridgewater associates",
      "quarter": "2025-q3",
      "issuer_queries": [
        {"issuer_query": "amazon", "cusip": "", "value": 0},
        {"issuer_query": "palantir", "cusip": "", "value": 0}
      ]
    },
    {
      "fund_query": "third point",
      "quarter": "2025-q3",
      "issuer_queries": [
        {"issuer_query": "amazon", "cusip": "", "value": 0},
        {"issuer_query": "palantir", "cusip": "", "value": 0}
      ]
    }
  ]
}
```

Requirements:
- Resolve each manager query against the Q3 cover page data.
- Resolve each issuer query to one stock CUSIP.
- For each manager and issuer pair, sum VALUE across all Q3 rows in that filing for the resolved CUSIP.
- Keep the manager order and issuer order exactly as shown.
- Use numeric values, not strings.
- Write only the JSON file requested.

